import{_ as t,l as r,o as e,c as o,v as l,p as m,x as i,d as s,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"Omni 模型对齐","description":"","frontmatter":{"title":"Omni 模型对齐","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/omni-model-alignment.md","filePath":"llm/omni-model-alignment.md","lastUpdated":1789023840000}'),h={name:"llm/omni-model-alignment.md"};function A(c,a,T,_,E,u){const n=r("Mermaid");return e(),o("div",null,[a[1]||(a[1]=l('<h1 id="omni-模型对齐" tabindex="-1">Omni 模型对齐 <a class="header-anchor" href="#omni-模型对齐" aria-label="Permalink to &quot;Omni 模型对齐&quot;">​</a></h1><div class="epigraph"><p>看、听、说、写进同一权重之后，对齐不再是单模态 RLHF。拒绝一张图、一段声、一句字，必须是同一套策略。</p><footer>—— 对照 Qwen2.5-Omni 等 Thinker–Talker 叙述；指令与安全仍落在共享语言骨干上</footer></div><p><a href="/llm/music-generation">上一课</a>与语音、图像生成器可以各训各的。缺口是 omni：多路编码器进共享 LLM，多路解码器出，训练混合与安全策略要一起定。后课音画同步是其中最硬的时间对齐，不替代本课的策略对齐。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/llava-projector">LLaVA 投影器</a> 只接一路视觉。<a href="/llm/clip">CLIP</a> 只拉图文。Omni 还要音频编码器、可选视觉生成头、语音出。Qwen2.5-Omni 把 Thinker（多模态理解 + 文本）与 Talker（流式语音出）分开，避免语音解码打乱语言隐状态。对齐问题变成：哪一路允许更新 LLM、如何混合损失、有害图像与有害语音是否共用拒答模板。</p><p>若视觉 SFT 与语音 SFT 分阶段且不回放，后训会洗掉先训的模态——和统一理解生成里「一种损失主导」相同。</p><p><span class="marginnote">输入侧越 omni，越要防跨模态越狱：图里写指令、音频里说覆盖系统提示。文本安全层看不见这些通道。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>架构上声明共享与分离（Thinker/Talker、双塔视觉）。训练：模态混合比例、指令模板跨模态一致、安全数据覆盖图/声/文。评测：各模态任务分列 + 跨模态一致性（同一问题用图问与用嘴问是否同策略）+ 越狱。不要用纯文本偏好模型直接给语音打分而不听。</p>',9)),(e(),m(p,null,{default:i(()=>[d(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E8%A7%86%E8%A7%89%22%5D%20--%3E%20TH%5B%22%E5%85%B1%E4%BA%AB%E7%90%86%E8%A7%A3%E9%AA%A8%E5%B9%B2%22%5D%0A%20%20A%5B%22%E9%9F%B3%E9%A2%91%22%5D%20--%3E%20TH%0A%20%20T%5B%22%E6%96%87%E6%9C%AC%22%5D%20--%3E%20TH%0A%20%20TH%20--%3E%20TXT%5B%22%E6%96%87%E6%9C%AC%E5%87%BA%22%5D%0A%20%20TH%20--%3E%20SPK%5B%22%E8%AF%AD%E9%9F%B3%E5%87%BA%E5%A4%B4%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>共享骨干让跨模态指代（「你刚才听到的那个，看图里有没有」）走同一套上下文。分离的 Talker 保护流式声学不回流污染文本推理。对齐损失若只加在文本，语音出可以念出文本已拒绝的内容——必须在出声头上也约束，或强制语音与已对齐文本一致。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>策略对齐不等于时间戳对齐。下一课专门钉口型、节拍与音画同步。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Omni 对齐是混合训练、拒答模板与跨模态越狱，不只是接更多编码器。</li><li>语音出头必须纳入约束，否则会念出文本已拒的内容。</li><li>评测要分列模态并做跨模态一致性。</li><li>出处：Qwen2.5-Omni 等 omni 系统叙述；投影与对比见 LLaVA / CLIP。</li></ul>',6))])}const k=t(h,[["render",A]]);export{B as __pageData,k as default};
